using System;
using System.Linq;
using System.IO;
using System.Drawing;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace UnturnedModManager {
 public partial class MainForm {
  Button reconcileButton;bool fittingBatch;Func<string,string> assistantStateResolver=Engine.DefaultAssistantState;
  void BuildReconciliationExperience(){
   InstallDirectChecks(grid);versionGrid.EditMode=DataGridViewEditMode.EditProgrammatically;InstallDirectChecks(versionGrid);
   reconcileButton=Button(L.Get("ReconcileInstall"),async delegate{var row=ReconciliationRow();if(row!=null)await ReconcileExisting(row);},L.Get("ReconcileHint"));autoFind.Parent.Controls.Add(reconcileButton);
   var footer=(TableLayoutPanel)status.Parent;footer.Controls.Remove(status);footer.Controls.Remove(progress);footer.ColumnCount=1;footer.RowCount=2;footer.ColumnStyles.Clear();footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.RowStyles.Clear();footer.RowStyles.Add(new RowStyle(SizeType.Absolute,26));footer.RowStyles.Add(new RowStyle(SizeType.Percent,100));progress.Margin=new Padding(2,2,2,4);footer.Controls.Add(status,0,0);footer.Controls.Add(progress,0,1);((TableLayoutPanel)footer.Parent).RowStyles[0].Height=56;workspaceRoot.RowStyles[5].Height=56;
   // Keep commands visible and let the flow layout wrap at narrow widths.
   var commandHost=batchBar.Parent;var commandSkin=commandHost.Parent;commandHost.Controls.Remove(batchBar);workspaceRoot.Controls.Remove(commandSkin);commandSkin.Dispose();var commands=(FlowLayoutPanel)batchBar;
   // ScrollSurface clips its child with a native window region. The command bar
   // now lives directly in the layout, so release that obsolete clipping region.
   var obsoleteRegion=commands.Region;commands.Region=null;if(obsoleteRegion!=null)obsoleteRegion.Dispose();
   commands.WrapContents=true;commands.AutoScroll=false;commands.Padding=new Padding(0,4,0,0);commands.Dock=DockStyle.Fill;workspaceRoot.Controls.Add(commands,0,4);commands.Layout+=delegate{FitBatchActions();};
   navigation.Padding=new Padding(4,8,4,4);navToggle.Height=44;UpdateNavigation();CaptureKeys(this);Theme(this);UpdateNavigation();UpdateSelection();
  }
  void FitBatchActions(){if(fittingBatch||batchBar==null||workspaceRoot==null||tabs.SelectedIndex!=0)return;fittingBatch=true;try{int width=Math.Max(1,batchBar.ClientSize.Width-batchBar.Padding.Horizontal),x=0,line=0,total=batchBar.Padding.Vertical;foreach(Control action in batchBar.Controls){if(!action.Visible)continue;int w=action.Width+action.Margin.Horizontal,h=action.Height+action.Margin.Vertical;if(x>0&&x+w>width){total+=line;x=0;line=0;}x+=w;line=Math.Max(line,h);}float height=total+line+4;if(workspaceRoot.RowStyles[4].Height!=height){workspaceRoot.RowStyles[4].Height=height;if(IsHandleCreated)BeginInvoke(new Action(delegate{if(!IsDisposed)workspaceRoot.PerformLayout();}));}}finally{fittingBatch=false;}FitNavigation();}
  void InstallDirectChecks(DataGridView view){((SmoothGrid)view).DirectCheck=index=>ToggleDirectCheck(view,index);}
  void ToggleDirectCheck(DataGridView view,int index){if(busy||index<0||index>=view.RowCount||view.Rows[index].Cells[0].ReadOnly||!view.Rows[index].Visible)return;var cell=view.Rows[index].Cells[0];if(view==grid)cell.Value=!Convert.ToBoolean(cell.Value);else{var parent=view.Rows[index].Tag as Row;var option=view.Rows[index].Tag as VersionOption;bool all=parent!=null?parent.Options.All(o=>checkedVersions.Contains(OptionId(o))):option!=null&&checkedVersions.Contains(OptionId(option));renderingVersions=true;try{if(parent!=null)foreach(var child in parent.Options)SetVersionChecked(child,!all);else if(option!=null)SetVersionChecked(option,!all);}finally{renderingVersions=false;}BeginInvoke(new Action(RefreshVersions));}view.InvalidateColumn(0);}
  Row ReconciliationRow(){var chosen=Selected();return chosen.Count==1?chosen[0]:CurrentRowModel();}
  void RefreshReconcileAction(){if(reconcileButton==null)return;var row=ReconciliationRow();reconcileButton.Enabled=!busy&&CatalogMatchesTarget()&&row!=null&&row.Package!=null&&row.Package.Manifest.kind=="localization"&&row.Package.Manifest.packageIdentity!=null;}
  async Task<bool> ReconcileExisting(Row row,string assistantOverride=null,bool showSuccess=true){if(busy||row.Package==null||!CatalogMatchesTarget())return false;try{string root=game.Text,scope=row.Package.Manifest.scopeId;bool server=serverMode;var roots=workshopLocations.ToArray();Engine engine=null;ReconciliationPlan plan=null;string assistant=null;SetBusy(true,true);try{await Task.Run(()=>{engine=new Engine(root,store,preview,server,scope,roots);assistant=assistantOverride??assistantStateResolver(engine.Root);});}finally{SetBusy(false);}if(!File.Exists(Path.Combine(assistant,"installed.json"))){if(Dialogs.Show(L.Get("ReconcileChoose"),Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return false;using(var picker=new FolderBrowserDialog{Description=L.Get("ReconcileChooseFolder")}){if(picker.ShowDialog(this)!=DialogResult.OK)return false;assistant=picker.SelectedPath;}}
   SetBusy(true,true);status.Text=L.Get("ReconcileChecking");try{plan=await Task.Run(()=>engine.ReviewReconciliation(row.Package,assistant));}finally{SetBusy(false);}if(plan.AlreadyCurrent){rowErrors.Remove(RowId(row));await RefreshInstalledState();status.Text=L.Get("ReconcileAligned");progress.Value=100;if(showSuccess)Dialogs.Show(L.Get("ReconcileAligned"),Text);return true;}string review=(showSuccess?"":L.Get("ReconcileBeforeInstall")+Environment.NewLine+Environment.NewLine)+string.Format(L.Get("ReconcileReview"),ModNames.Display(plan.Package),plan.Package.Manifest.version,engine.Root,plan.Files,plan.Originals,plan.Retained,plan.RetainedDifferences,plan.BackupDifferences)+Environment.NewLine+Environment.NewLine+L.Get("ReconcileConsent");if(Dialogs.Show(review,L.Get("ReconcileInstall"),MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return false;
   string history=null;SetBusy(true,true);try{history=await Task.Run(()=>engine.Reconcile(plan));rowErrors.Remove(RowId(row));}finally{SetBusy(false);}await RefreshInstalledState();RefreshProblems();for(int i=0;i<rows.Count;i++)RefreshRow(i);string summary=L.Get("ReconcileComplete");status.Text=summary;progress.Value=100;AddActivity(summary,"Success",RowId(row),L.Get("ReconcileInstall"));if(showSuccess)ShowResult(summary,string.Format(L.Get("ReconcileSummary"),plan.Files,plan.Originals,plan.Retained)+Environment.NewLine+(history??""),new System.Collections.Generic.List<string>());return true;
  }catch(Exception ex){RecordRowError(row,ex);Error(ex);return false;}}
 }
}
